mapper.select:
   SELECT o.id,o.custom_order_no number,o.version,o.requirement_id,o.factory_id,
          o.order_status state,q.total_amount_fen total_fen,o.updated_at FROM custom_order o JOIN custom_quote q ON q.id=o.accepted_quote_id WHERE o.factory_id=#{factory}o.buyer_user_id=#{buyer}
AND o.order_status=#{status} ORDER BY o.updated_at DESC,o.id LIMIT #{page.pageSize} OFFSET #{page.offset}
